import Foundation

/// Turns what happened in a rehearsal into household-specific preparation cards.
/// Triggers are deterministic predicates over the run summary; nothing is generated by a model.
public enum ActionRules {
    static func isVulnerable(_ h: HouseholdProfile) -> Bool {
        h.people.contains { p in
            !p.needs.isEmpty || p.ageBand == .infant || p.ageBand == .olderAdult
        } || h.equipment.contains { $0.isEssential }
    }

    /// Trying a relocation preparation also uses it: the replay takes the first applicable, safe relocation option.
    static func relocationChoice(_ s: RunSummary) -> [String: String] {
        for cp in s.scenario.choicePoints.sorted(by: { ($0.minute, $0.id) < ($1.minute, $1.id) })
        where Applicability.holds(cp.when, household: s.household, home: s.home, variants: s.variants) {
            if let o = cp.options.first(where: { !$0.unsafe && ($0.effect == "relocate" || $0.effect == "leaveEarly") }) {
                return [cp.id: o.id]
            }
        }
        return [:]
    }

    public static func evaluate(_ s: RunSummary, catalog: ActionCatalog) -> [Recommendation] {
        var out: [Recommendation] = []
        let h = s.household
        let scen = s.scenario.id

        func add(_ id: String, tier: PriorityTier, facts: [String], causes reqs: [String] = [], values: [String: String] = [:],
                 tryParams: [String: String]? = nil, unconfirmed: [String] = [], status: EvidenceStatus = .needsVerification,
                 whySuffix: String? = nil) {
            guard let def = catalog.action(id) else { return }
            let causeIDs = reqs.flatMap { s.causes[$0] ?? [] }
            var notes = def.feasibilityNotes
            if h.housing.tenancy == .renter, !def.renterFriendly { notes.append("feasibility.renter-permission") }
            if h.supplies.limitedBudget, def.effort == .moderate || def.effort == .high { notes.append("feasibility.budget") }
            func subject(_ prefix: String, ids: [String]) -> String? {
                // IDs may contain dots. Match declared subjects, preferring the longest exact prefix.
                ids.sorted { ($0.count, $0) > ($1.count, $1) }.first { id in
                    facts.contains { $0 == "\(prefix).\(id)" || $0.hasPrefix("\(prefix).\(id).") }
                }.map { "\(prefix).\($0)" }
            }
            let subjectID = values["device"] != nil ? subject("equipment", ids: h.equipment.map(\.id))
                : (values["person"] != nil ? subject("person", ids: h.people.map(\.id))
                   : (values["backup"] != nil ? subject("backup", ids: h.backupPower.map(\.id)) : nil))
            out.append(Recommendation(
                actionID: id, tier: tier, titleKey: "action.\(id).title", whyKey: "action.\(id).why" + (whySuffix.map { ".\($0)" } ?? ""), templateValues: values,
                matchedFactIDs: facts, causeEventIDs: Array(Set(causeIDs)).sorted(), scenarioIDs: def.scenarioIDs,
                tryIntervention: def.simulates != nil ? Intervention(actionID: id, parameters: tryParams ?? [:]) : nil,
                modeledEffectKey: def.simulates != nil ? "action.\(id).effect" : nil, effort: def.effort,
                feasibilityNotes: notes, unconfirmed: unconfirmed, sourceIDs: def.sourceIDs, verificationStatus: status, subjectID: subjectID))
        }

        // Essential powered equipment.
        for eq in h.equipment.sorted(by: { $0.id < $1.id }) where eq.isEssential {
            if s.unmetEver.contains("req.power.\(eq.id)") {
                let unconf = ["equipment.\(eq.id).runtime"]
                add("act.backup.confirm-medical-backup", tier: .unmetEssentialRequirement,
                    facts: ["equipment.\(eq.id)"] + h.backupPower.map { "backup.\($0.id).setupConfirmed" },
                    causes: ["req.power.\(eq.id)"], values: ["device": eq.label], tryParams: ["equipment": eq.id], unconfirmed: unconf)
                add("act.medical.continuity-plan", tier: .unmetEssentialRequirement, facts: ["equipment.\(eq.id)"],
                    causes: ["req.power.\(eq.id)"], values: ["device": eq.label])
            }
            if s.unknowns.contains("equipment.\(eq.id).runtime") || s.unknowns.contains("equipment.\(eq.id).backupOutcome") {
                add("act.medical.document-runtime", tier: .blockingUnknownFact, facts: ["equipment.\(eq.id).documentedBackupRuntimeHours"],
                    values: ["device": eq.label], unconfirmed: ["equipment.\(eq.id).runtime"], status: .unknown)
            }
            if s.unmetEver.contains("req.refrigeration.\(eq.id)") {
                if h.supplies.coolerAndIcePacks.confirmedValue != true {
                    add("act.refrigeration.cooler-plan", tier: .unmetEssentialRequirement, facts: ["equipment.\(eq.id)", "supplies.coolerAndIcePacks"],
                        causes: ["req.refrigeration.\(eq.id)"], values: ["device": eq.label])
                }
                add("act.medical.continuity-plan", tier: .unmetEssentialRequirement, facts: ["equipment.\(eq.id)"],
                    causes: ["req.refrigeration.\(eq.id)"], values: ["device": eq.label])
            }
        }

        // Relocation (heat/cold access, displacement, flood, manufactured-home tornado plan).
        let needsRelocation = s.unmetEver.contains("req.relocation")
            || (s.unmetEver.contains("req.heat") && s.scenario.ambient == "cold")
            || (s.unmetEver.contains("req.cooling") && s.scenario.ambient == "hot")
        let relocationReady = s.finalServices[Svc.transport] == .operational && s.finalServices[Svc.destination] == .operational
        if needsRelocation && !relocationReady && scen != "tornado" {
            var facts = ["transport.destinations"]
            if !h.transport.hasVehicle { facts.append("transport.vehicles") }
            facts.append("transport.alternatives")
            let reason = s.scenario.ambient == "hot" ? "cooling" : (s.scenario.ambient == "cold" ? "heat" : "displacement")
            add("act.relocation.arrange", tier: isVulnerable(h) ? .unmetEssentialRequirement : .scenarioSupplyOrContinuityGap,
                facts: facts, causes: ["req.relocation", "req.heat", "req.cooling"],
                values: ["context": reason, "vehicle": h.transport.hasVehicle ? "yes" : "no"], tryParams: relocationChoice(s),
                unconfirmed: ["transport.destinations.conditions"], whySuffix: reason)
        }

        // Assistance.
        for p in h.people where s.unmetEver.contains("req.assistance.\(p.id)") {
            add("act.assist.assign-helper", tier: .unmetEssentialRequirement, facts: ["person.\(p.id).needs"],
                causes: ["req.assistance.\(p.id)"], values: ["person": p.alias])
        }

        for p in h.people where s.unmetEver.contains("req.assistance.reach.\(p.id)") {
            let helper = h.people.first { $0.id == p.helperPersonID }?.alias ?? ""
            add("act.fire.helper-reach-plan", tier: .unmetEssentialRequirement,
                facts: ["person.\(p.id).helperPersonID", "person.\(p.id).sleepingSpaceID"],
                causes: ["req.assistance.reach.\(p.id)"], values: ["person": p.alias, "helper": helper])
        }

        // Tornado.
        if s.unmetEver.contains("req.shelter") {
            add("act.tornado.choose-shelter", tier: .unmetEssentialRequirement, facts: ["home.spaces"], causes: ["req.shelter"])
        }
        if s.unmetEver.contains("req.shelter.sturdyBuilding") {
            add("act.tornado.sturdy-building-plan", tier: .unmetEssentialRequirement, facts: ["housing.homeType"],
                causes: ["req.shelter.sturdyBuilding"], tryParams: relocationChoice(s))
        }
        if s.unmetEver.contains("req.alerts.night") {
            add("act.comms.weather-radio", tier: .unmetEssentialRequirement, facts: ["communications.batteryOrCrankRadio"],
                causes: ["req.alerts.night"])
        }

        // Fire.
        if s.flags.contains("fire.noRoute") {
            add("act.fire.verify-second-exit", tier: .unmetEssentialRequirement, facts: ["home.portals"],
                causes: h.people.map { "req.egress.\($0.id)" })
        } else if s.flags.contains("fire.noIndependentSecondExit") {
            add("act.fire.verify-second-exit", tier: .blockingUnknownFact, facts: ["home.portals"])
        }
        if s.unmetEver.contains("req.meetingPoint") {
            add("act.fire.meeting-point", tier: .blockingUnknownFact, facts: ["home.annotations"], causes: ["req.meetingPoint"])
        }
        if s.flags.contains("fire.smokeAlarmsUnverified") {
            add("act.fire.smoke-alarms", tier: .blockingUnknownFact, facts: ["home.annotations"], status: .unknown)
        }
        if scen == "home-fire" { add("act.fire.practice-drill", tier: .general, facts: []) }

        // Heating dependency unknown.
        if s.unknowns.contains("housing.heatingNeedsElectricity"), s.scenario.ambient == "cold" || scen == "freeze-power-loss" {
            add("act.heat.ask-blower", tier: .blockingUnknownFact, facts: ["housing.heatingNeedsElectricity"], status: .unknown)
        }

        // Water.
        let waterRelevant = s.unmetEver.contains("req.water") || s.flags.contains("water.belowTarget")
        if waterRelevant {
            let target = Double(h.people.count) * 3
            add("act.water.store-3day", tier: .scenarioSupplyOrContinuityGap, facts: ["supplies.storedWaterGallons", "people"],
                causes: ["req.water"], values: ["target": Fmt.num(target), "stored": Fmt.opt(h.supplies.storedWaterGallons.confirmedValue),
                                                 "people": String(h.people.count)],
                unconfirmed: h.pets.isEmpty ? [] : ["pets.waterNeeds"],
                whySuffix: h.supplies.storedWaterGallons.isConfirmed ? nil : "unknown")
        }
        if scen == "water-outage" || s.flags.contains(where: { $0.hasPrefix("advisory.") }) {
            add("act.water.save-utility-contact", tier: .multiScenarioPreparation, facts: ["housing.waterSource"])
        }
        if scen == "flash-flood", h.housing.waterSource == .privateWell {
            add("act.water.well-test-after-flood", tier: .scenarioSupplyOrContinuityGap, facts: ["housing.waterSource"])
        }
        if scen == "flash-flood" { add("act.flood.higher-ground-plan", tier: .multiScenarioPreparation, facts: []) }

        // Communications.
        if s.unmetEver.contains("req.comms.handset") {
            add("act.comms.power-bank", tier: .scenarioSupplyOrContinuityGap, facts: ["communications.powerBankCharges", "communications.handsetRuntimeHours"],
                causes: ["req.comms.handset"])
            if h.communications.batteryOrCrankRadio.confirmedValue != true, !s.unmetEver.contains("req.alerts.night") {
                add("act.comms.weather-radio", tier: .multiScenarioPreparation, facts: ["communications.batteryOrCrankRadio"])
            }
        }

        // Pets when leaving home is part of the plan.
        if !h.pets.isEmpty, h.pets.contains(where: { $0.carrierAvailable.confirmedValue != true }),
           needsRelocation || s.flags.contains("fire") {
            add("act.pets.carrier-plan", tier: .scenarioSupplyOrContinuityGap, facts: h.pets.map { "pet.\($0.id).carrierAvailable" })
        }

        // Generator placement safety.
        for b in h.backupPower where b.kind == .portableGenerator && b.safeOutdoorPlacementConfirmed.confirmedValue != true {
            add("act.generator.outdoor-placement", tier: .unmetEssentialRequirement, facts: ["backup.\(b.id).safeOutdoorPlacementConfirmed"],
                values: ["backup": b.label])
        }

        // Cross-scenario, no cost.
        add("act.alerts.enroll-local", tier: .multiScenarioPreparation, facts: ["regionID"])
        return out
    }
}

/// Lexicographic ranking with deterministic tie-breaking:
///  1. priority tier (unmet essential < blocking unknown < scenario gap < multi-scenario < general)
///  2. effort band (no-cost first) — only *within* a tier, so price never outranks a critical dependency
///  3. number of scenarios the preparation helps (more first)
///  4. action ID (stable)
/// Duplicate action IDs are merged, keeping the most urgent tier and the union of facts and causes.
public enum RecommendationRanker {
    static func effortRank(_ e: EffortBand) -> Int {
        switch e { case .noCost: 0; case .low: 1; case .moderate: 2; case .high: 3 }
    }

    public static func rank(_ recs: [Recommendation]) -> [Recommendation] {
        var merged: [String: Recommendation] = [:]
        for r in recs {
            if var existing = merged[r.id] {
                if r.tier < existing.tier {
                    var keep = r
                    keep.matchedFactIDs = Array(Set(existing.matchedFactIDs + r.matchedFactIDs)).sorted()
                    keep.causeEventIDs = Array(Set(existing.causeEventIDs + r.causeEventIDs)).sorted()
                    merged[r.id] = keep
                } else {
                    existing.matchedFactIDs = Array(Set(existing.matchedFactIDs + r.matchedFactIDs)).sorted()
                    existing.causeEventIDs = Array(Set(existing.causeEventIDs + r.causeEventIDs)).sorted()
                    for (k, v) in r.templateValues where existing.templateValues[k] == nil { existing.templateValues[k] = v }
                    merged[r.id] = existing
                }
            } else {
                var r2 = r
                r2.matchedFactIDs = Array(Set(r.matchedFactIDs)).sorted()
                merged[r.id] = r2
            }
        }
        return merged.values.sorted { a, b in
            (a.tier.rawValue, effortRank(a.effort), -a.scenarioIDs.count, a.id)
                < (b.tier.rawValue, effortRank(b.effort), -b.scenarioIDs.count, b.id)
        }
    }
}

/// Structured baseline/modified comparison.
public enum RehearsalDiffer {
    public static func diff(_ a: RehearsalResult, _ b: RehearsalResult) -> RehearsalDiff {
        let ea = Set(a.events.map(\.id)), eb = Set(b.events.map(\.id))
        let fa = a.snapshots.last?.services ?? [:], fb = b.snapshots.last?.services ?? [:]
        var svc: [String: [ServiceState]] = [:]
        // Compare the worst state reached as well as the final state.
        let worstA = worst(a), worstB = worst(b)
        for k in Set(worstA.keys).union(worstB.keys).sorted() {
            let x = worstA[k] ?? .unknown, y = worstB[k] ?? .unknown
            if x != y { svc[k] = [x, y] }
        }
        for k in Set(fa.keys).union(fb.keys) where svc[k] == nil && fa[k] != fb[k] {
            svc[k] = [fa[k] ?? .unknown, fb[k] ?? .unknown]
        }
        let ua = Set(a.snapshots.flatMap(\.unmetRequirements)), ub = Set(b.snapshots.flatMap(\.unmetRequirements))
        var res: [String: [ResourceQuantity]] = [:]
        let ra = a.snapshots.last?.resources ?? [:], rb = b.snapshots.last?.resources ?? [:]
        for k in Set(ra.keys).union(rb.keys) where ra[k] != rb[k] {
            res[k] = [ra[k] ?? ResourceQuantity(amount: nil, unit: rb[k]?.unit ?? ""), rb[k] ?? ResourceQuantity(amount: nil, unit: ra[k]?.unit ?? "")]
        }
        let recA = Set(a.recommendations.map(\.actionID)), recB = Set(b.recommendations.map(\.actionID))
        return RehearsalDiff(addedEventIDs: eb.subtracting(ea).sorted(), removedEventIDs: ea.subtracting(eb).sorted(), serviceChanges: svc,
                             resolvedRequirements: ua.subtracting(ub).sorted(), newRequirements: ub.subtracting(ua).sorted(),
                             resourceChanges: res, resolvedRecommendations: recA.subtracting(recB).sorted())
    }

    static func severity(_ s: ServiceState) -> Int {
        switch s { case .operational: 0; case .degraded: 1; case .unknown: 2; case .unavailable: 3 }
    }

    static func worst(_ r: RehearsalResult) -> [String: ServiceState] {
        var out: [String: ServiceState] = [:]
        for snap in r.snapshots { for (k, v) in snap.services where severity(v) > severity(out[k] ?? .operational) || out[k] == nil { out[k] = v } }
        return out
    }
}
